import{LOVEBOARD_PDF,LOVEBOARD_PDF_PAGES}from './loveboard-service-source.js?v=20261111-94';
const l=s=>s.split('|');
const step=(title,body,refs,action,extra={})=>({title:l(title),body:l(body),refs,...(action?{action}:{}),...extra});
export const LOVEBOARD_TASK={id:'loveboard',category:2,revision:1,title:l('LoveBoardを交換する|Replace the LoveBoard|Výměna desky LoveBoard|LoveBoard austauschen'),interval:l('交換が必要なとき|When replacement is needed|Při potřebě výměny|Bei erforderlichem Austausch'),source:'https://help.prusa3d.com/guide/how-to-replace-loveboard-core-one_958922',steps:[
 step('作業を始める前に|Before starting|Před zahájením|Vor Beginn','CORE One／One+のLoveBoard交換手順です。交換基板と工具を先に用意します。|This procedure replaces the LoveBoard on CORE One / One+. Prepare the replacement board and tools first.|Postup výměny desky LoveBoard u CORE One / One+. Nejprve připravte novou desku a nářadí.|Austausch des LoveBoards am CORE One / One+. Ersatzplatine und Werkzeug bereitlegen.',['loveBoard']),
 step('工具を用意する|Prepare the tools|Příprava nářadí|Werkzeug vorbereiten','2.5 mm六角レンチとT10キーまたはドライバーを用意します。|Prepare a 2.5 mm Allen key and a T10 key or screwdriver.|Připravte 2,5mm imbus a klíč nebo šroubovák T10.|2,5-mm-Inbusschlüssel und T10-Schlüssel oder -Schraubendreher bereitlegen.',['loveBoard',847]),
 step('アンロードして冷却する|Unload and cool down|Vysunutí filamentu a ochlazení|Entladen und abkühlen','ドアを閉じ、Filament → Unload filamentでアンロードします。スプールを外し、Preheat → COOLDOWNで室温まで冷却します。|Close the door. Use Filament → Unload filament, remove the spool, then select Preheat → COOLDOWN and wait for ambient temperature.|Zavřete dvířka. Zvolte Filament → Unload filament, odeberte cívku a přes Preheat → COOLDOWN vyčkejte na pokojovou teplotu.|Tür schließen. Filament → Unload filament ausführen, Spule abnehmen und über Preheat → COOLDOWN auf Raumtemperatur abkühlen.',['lcd','hotend'],null,{firmwareActions:["unload","cooldown"]}),
 step('ベッドを下げて電源を切る|Lower the bed and disconnect power|Spuštění podložky a odpojení|Heizbett absenken und Netz trennen','Control → Move Axis → Move Zで100 mm以上に下げます。停止を待って電源を切り、電源コードを抜きます。|Set Control → Move Axis → Move Z to at least 100 mm. Wait for movement to stop, switch off and unplug.|V Control → Move Axis → Move Z nastavte alespoň 100 mm. Vyčkejte na zastavení, vypněte a odpojte přívod.|Control → Move Axis → Move Z auf mindestens 100 mm stellen. Stillstand abwarten, ausschalten und Netzstecker ziehen.',['bedSupport','heatbed','sheet','psu'],'lb-bed-down',{firmwareActions:["moveZ"]}),
 step('上面カバーを外す|Remove the top cover|Sejmutí horního krytu|Oberen Deckel abnehmen','内側からナイロンリベットを押して解除し、外から抜きます。残りも外して上面カバーを持ち上げます。|Release the nylon rivets from inside and pull them out from outside. Remove the remaining rivets and lift off the cover.|Nylonové nýty odjistěte zevnitř a vytáhněte zvenku. Vyjměte zbývající nýty a zvedněte kryt.|Nylonnieten von innen entriegeln und außen herausziehen. Übrige Nieten entfernen und Deckel abheben.',[87,'ventBlock'],'lb-top-out'),
 step('ヒートベッドを保護する|Protect the heatbed|Ochrana vyhřívané podložky|Heizbett schützen','厚手の布などでベッドを覆い、落とした工具や部品で傷を付けないようにします。|Cover the bed with sufficiently thick fabric to protect it from tools and parts.|Podložku zakryjte dostatečně silnou látkou proti poškození nářadím a díly.|Heizbett mit ausreichend dickem Stoff vor Werkzeug und Teilen schützen.',['heatbed']),
 step('左カバーを外す|Remove the left cover|Sejmutí levého krytu|Linke Abdeckung abnehmen','M3×10を外します。カバーを外側へ開き、下側の掛かりを抜きます。|Remove the M3×10. Open the cover outward and release its lower hook.|Vyšroubujte M3×10. Kryt odklopte ven a uvolněte spodní háček.|M3×10 entfernen. Abdeckung nach außen öffnen und unten aushaken.',[858,879],'lb-cover-out'),
 step('ホットエンドを抜線する|Disconnect the hotend|Odpojení hotendu|Hotend abstecken','ラッチを押してヒーター、サーミスターの順に抜きます。配線を引っ張らないでください。|Press the latches and unplug the heater, then the thermistor. Do not pull the wires.|Stiskněte západky a odpojte topení, poté termistor. Netahejte za vodiče.|Verriegelungen drücken und Heizung, dann Thermistor abstecken. Nicht an Leitungen ziehen.',['hotendHeater0','hotendThermistor0','loveBoard'],'lb-hotend-unplug'),
 step('ホットエンドを支えて抜く|Support and withdraw the hotend|Podepření a vyjmutí hotendu|Hotend halten und herausziehen','ケーブルをガイドから外し、ホットエンドを手で支えます。つまみネジ2本を数回転緩め、ヒートシンクから下へ抜きます。ネジは抜き切りません。|Free the cables from the guide and support the hotend. Loosen both thumbscrews a few turns and withdraw downward. Keep the screws in place.|Uvolněte kabely z vedení a hotend podepřete. Oba ruční šrouby povolte o několik otáček a hotend vysuňte dolů. Šrouby nevyjímejte.|Kabel aus der Führung lösen und Hotend halten. Beide Rändelschrauben einige Umdrehungen lockern und Hotend nach unten ziehen. Schrauben nicht ganz entfernen.',['hotend',795,807],'lb-hotend-out'),
 step('左側と上面の配線を抜く|Disconnect left and top leads|Odpojení levých a horních kabelů|Linke und obere Leitungen lösen','各コネクターの解除バーを指の腹で押し、ロックを外してからまっすぐ抜きます。プリントファンの配線を後ろへ逃がし、上面のモーター、ヒートシンクのNTC、ホットエンドファンの順に外します。|Unplug the print fan and move its lead back. Disconnect the top motor, heatsink NTC and hotend fan.|Odpojte tiskový ventilátor a kabel odsuňte dozadu. Odpojte horní motor, NTC chladiče a ventilátor hotendu.|Drucklüfter abstecken und Kabel nach hinten legen. Motor oben, Kühlkörper-NTC und Hotend-Lüfter abstecken.',['loveBoard','lbMotorLead','lbNtcLead','servicePrintLead','serviceHotendFanLead'],'lb-left-unplug'),
 step('右カバーとセンサー配線を外す|Remove right cover and sensor leads|Pravý kryt a kabely senzorů|Rechte Abdeckung und Sensorkabel lösen','右側のM3×6を2本外してカバーを外します。ロードセル、フィラメントセンサーの順に、解除バーを押してロックを外し、まっすぐ抜きます。|Remove the two right-side M3×6 screws and cover. Unplug the loadcell and filament sensor.|Vyjměte dva pravé šrouby M3×6 a kryt. Odpojte loadcell a senzor filamentu.|Zwei rechte M3×6 und Abdeckung entfernen. Wägezelle und Filamentsensor abstecken.',['ventLever',870,872,'lbLoadcellLead','lbFilamentLead'],'lb-right-out'),
 step('ホットエンドファンを外す|Remove the hotend fan|Demontáž ventilátoru hotendu|Hotend-Lüfter ausbauen','M3×18を2本外し、ヒートシンクからファンを外します。|Remove both M3×18 screws and lift the fan away from the heatsink.|Vyjměte oba šrouby M3×18 a sejměte ventilátor z chladiče.|Beide M3×18 entfernen und Lüfter vom Kühlkörper abnehmen.',[791,819,821],'lb-hotfan-out'),
 step('Nextruderを外す|Remove the Nextruder|Demontáž Nextruderu|Nextruder ausbauen','正面のM3×10を3本外します。Nextruderを支えて上のPTFE継手を緩め、ゆっくり取り外します。NTCの配線をキャリッジのフックから外し、引っ掛けないでください。|Remove the three front M3×10 screws. Support the Nextruder, unscrew the top PTFE fitting and withdraw slowly. Release the NTC lead from the carriage hook.|Vyjměte tři přední M3×10. Nextruder podepřete, vyšroubujte horní PTFE šroubení a pomalu jej sejměte. Kabel NTC uvolněte z háčku vozíku.|Drei vordere M3×10 entfernen. Nextruder halten, obere PTFE-Verschraubung lösen und langsam abnehmen. NTC-Leitung aus dem Wagenhaken lösen.',[788,'lbNtcLead'],'lb-nextruder-out'),
 step('プリントファンと背面カバーを外す|Remove print fan and rear cover|Tiskový ventilátor a zadní kryt|Drucklüfter und Rückabdeckung ausbauen','ファンのM3×20を外し、ファンを上へ持ち上げます。背面のM3×10を2本外し、カバーを外します。メインケーブルを溝から外しますが、全体を抜き取らないでください。取り外したネジは保管し、組み戻す際に同じ位置へ戻します。|Remove the fan M3×20 and lift the fan upward. Remove two rear M3×10 screws and the cover. Release the main cable from its groove without removing it entirely. Keep the removed screws and return each to its original position.|Vyjměte M3×20 ventilátoru a zvedněte ventilátor nahoru. Vyjměte dva zadní M3×10 a kryt. Hlavní kabel uvolněte z drážky, ale nevytahujte jej celý. Vyjmuté šrouby uschovejte a vraťte je na původní místa.|Lüfter-M3×20 entfernen und Lüfter nach oben heben. Zwei hintere M3×10 und Abdeckung entfernen. Hauptkabel aus der Nut lösen, jedoch nicht vollständig herausziehen. Ausgebaute Schrauben aufbewahren und wieder an derselben Stelle einsetzen.',[833,845,860,864,866,'lbMainLead'],'lb-rear-out'),
 step('LoveBoardを外す|Remove the LoveBoard|Vyjmutí desky LoveBoard|LoveBoard ausbauen','正面でメインコネクターを抜きます。背面のM3×8rTをT10で外し、基板の端を持って取り外します。|Unplug the main connector at the front. Remove the rear M3×8rT with T10 and lift the board by its edges.|Vpředu odpojte hlavní konektor. Vzadu vyšroubujte M3×8rT klíčem T10 a desku vyjměte za hrany.|Hauptstecker vorne lösen. Hintere M3×8rT mit T10 entfernen und Platine an den Kanten abnehmen.',['loveBoard',847,'lbMainLead'],'lb-board-out'),
 step('交換基板を用意する|Prepare the replacement board|Příprava nové desky|Ersatzplatine vorbereiten','LoveBoardを1枚用意します。端子の向きと固定穴を公式写真で確認します。|Prepare one LoveBoard. Check connector orientation and the mounting hole against the official photo.|Připravte jednu desku LoveBoard. Orientaci konektorů a otvor ověřte podle oficiální fotografie.|Ein LoveBoard bereitlegen. Steckerausrichtung und Befestigungsloch mit dem offiziellen Foto abgleichen.',['loveBoard']),
 step('LoveBoardを取り付ける|Install the LoveBoard|Montáž desky LoveBoard|LoveBoard einbauen','メインケーブルを基板の下へ通し、挟まないよう基板を取り付けます。M3×8rTで固定してメイン端子を接続します。キャリッジ正面に配線が張り出さないよう整えます。|Route the main cable beneath the board without pinching it. Fit the board, secure with M3×8rT and connect the main plug. Keep the carriage front clear of overhanging wires.|Hlavní kabel veďte pod deskou a neskřípněte jej. Desku upevněte M3×8rT a připojte hlavní konektor. Vodiče nesmějí přečnívat před vozík.|Hauptkabel unter der Platine führen, ohne es einzuklemmen. Platine mit M3×8rT befestigen und Hauptstecker anschließen. Leitungen dürfen vorne nicht über den Wagen ragen.',['loveBoard',847,'lbMainLead'],'lb-board-in'),
 step('背面カバーとプリントファンを戻す|Refit rear cover and print fan|Zadní kryt a tiskový ventilátor|Rückabdeckung und Drucklüfter montieren','メインケーブルを上部の溝へ通します。配線を挟まず背面カバーをM3×10の2本で固定します。ファンを戻しM3×20で固定、ケーブルを専用溝で前へ通します。|Route the main cable in the upper groove. Refit the rear cover with two M3×10 without pinching wires. Fit the fan with M3×20 and route its lead forward through the channel.|Hlavní kabel veďte horní drážkou. Zadní kryt upevněte dvěma M3×10 bez skřípnutí vodičů. Ventilátor zajistěte M3×20 a kabel veďte kanálem dopředu.|Hauptkabel in die obere Nut führen. Rückabdeckung ohne gequetschte Leitungen mit zwei M3×10 befestigen. Lüfter mit M3×20 montieren und Kabel im Kanal nach vorne führen.',[860,864,866,833,845],'lb-rear-in'),
 step('Nextruderを戻す|Refit the Nextruder|Montáž Nextruderu|Nextruder montieren','NTCの配線をキャリッジのフックへ通します。ヒートシンク裏で挟まず、Nextruderを合わせてPTFE継手で保持します。正面のM3×10を3本締めます。|Guide the NTC lead through the carriage hook, clear of the heatsink rear. Align the Nextruder, retain it with the PTFE fitting and secure three front M3×10 screws.|Kabel NTC veďte háčkem vozíku mimo zadní stranu chladiče. Nextruder srovnejte, přidržte PTFE šroubením a upevněte třemi předními M3×10.|NTC-Kabel durch den Wagenhaken führen, nicht hinter dem Kühlkörper einklemmen. Nextruder ausrichten, mit PTFE-Verschraubung halten und drei vordere M3×10 befestigen.',[788,'lbNtcLead'],'lb-nextruder-in'),
 step('ホットエンドファンを戻す|Refit the hotend fan|Montáž ventilátoru hotendu|Hotend-Lüfter montieren','銀色ラベルをヒートシンク側、配線を左へ向けます。M3×18を2本使って固定します。|Face the silver label toward the heatsink and the cable left. Secure with two M3×18 screws.|Stříbrný štítek směřuje k chladiči a kabel doleva. Upevněte dvěma M3×18.|Silbernes Etikett zum Kühlkörper und Kabel nach links ausrichten. Mit zwei M3×18 befestigen.',[791,819,821],'lb-hotfan-in'),
 step('右側センサーを接続する|Reconnect right-side sensors|Připojení pravých senzorů|Rechte Sensoren anschließen','ロードセルとフィラメントセンサーを接続します。右カバーを戻し、M3×6を2本締めます。|Connect the loadcell and filament sensor. Refit the right cover with two M3×6 screws.|Připojte loadcell a senzor filamentu. Pravý kryt připevněte dvěma M3×6.|Wägezelle und Filamentsensor anschließen. Rechte Abdeckung mit zwei M3×6 montieren.',['ventLever','lbLoadcellLead','lbFilamentLead'],'lb-right-in'),
 step('モーター・NTC・ファンを接続する|Connect motor, NTC and fan|Motor, NTC a ventilátor|Motor, NTC und Lüfter anschließen','上のモーター端子を接続します。左の内側寄りにNTC、左下にヒートシンクファンを接続します。|Connect the motor on top. Connect the heatsink NTC to the inner left port and the heatsink fan to the lower left port.|Připojte motor nahoře. NTC chladiče patří do vnitřního levého portu a ventilátor chladiče do dolního levého portu.|Motor oben anschließen. Kühlkörper-NTC an den inneren linken, Kühlkörperlüfter an den unteren linken Anschluss stecken.',['lbMotorLead','lbNtcLead','serviceHotendFanLead','loveBoard'],'lb-left-plug'),
 step('プリントファンを接続する|Connect the print fan|Připojení tiskového ventilátoru|Drucklüfter anschließen','ケーブルをカバーの溝へ通します。配線スペースでループを作り、LoveBoard左側の中央端子へ差し込みます。|Route the lead through the cover channel. Form a loop in the cable area and plug it into the middle left LoveBoard connector.|Kabel veďte kanálem krytu. V prostoru pro kabely vytvořte smyčku a připojte prostřední levý konektor LoveBoardu.|Kabel im Abdeckungskanal führen. Im Kabelraum eine Schlaufe bilden und in den mittleren linken LoveBoard-Anschluss stecken.',['servicePrintLead',833,'loveBoard'],'lb-print-plug'),
 step('ホットエンドを差し込む|Insert the hotend|Zasunutí hotendu|Hotend einsetzen','ケーブルを少し斜め前へ向け、ホットエンドを奥まで上へ押し込みます。ファンシュラウドとの隙間を確認し、押し上げたままつまみネジを締めます。|Point the cables slightly forward and push the hotend fully upward. Check shroud clearance and tighten both thumbscrews while supporting it upward.|Kabely natočte mírně dopředu a hotend zatlačte zcela nahoru. Ověřte vůli u krytu ventilátoru a při přidržování utáhněte oba ruční šrouby.|Kabel leicht nach vorne richten und Hotend ganz nach oben drücken. Abstand zur Lüfterhaube prüfen und beim Hochdrücken beide Rändelschrauben festziehen.',['hotend',795,807],'lb-hotend-in'),
 step('ノズルの挿入を確認する|Check nozzle seating|Kontrola zasunutí trysky|Düsensitz prüfen','銅色のリングが見えない位置まで挿入します。見える場合はネジを緩め、押し上げてから締め直します。|The copper ring must be hidden inside the heatsink. If visible, loosen the screws, push the nozzle up and retighten.|Měděný kroužek musí být schovaný v chladiči. Je-li vidět, šrouby povolte, trysku zatlačte nahoru a znovu utáhněte.|Kupferring muss im Kühlkörper verschwinden. Falls sichtbar, Schrauben lockern, Düse hochdrücken und wieder festziehen.',['hotend',794]),
 step('ケーブルをガイドへ通す|Route the hotend leads|Vedení kabelů hotendu|Hotend-Leitungen führen','つまみネジの後ろのフックへ、サーミスター、ヒーターの順に通します。|Route the thermistor first, then the heater, through the hook behind the thumbscrews.|Háčkem za ručními šrouby veďte nejprve termistor a potom topení.|Erst Thermistor, dann Heizung durch den Haken hinter den Rändelschrauben führen.',['hotendThermistor0','hotendHeater0',857],'lb-hotend-route'),
 step('ホットエンドを接続する|Connect the hotend|Připojení hotendu|Hotend anschließen','サーミスターをLoveBoard左上の端子、ヒーターを上部の黒い端子へ接続します。|Connect the thermistor to the upper left slot and the heater to the black upper socket.|Termistor připojte do levé horní zdířky, topení do horního černého konektoru.|Thermistor oben links und Heizung an die schwarze obere Buchse anschließen.',['hotendThermistor0','hotendHeater0','loveBoard'],'lb-hotend-plug'),
 step('左カバーを戻す|Refit the left cover|Nasazení levého krytu|Linke Abdeckung montieren','配線を内側へ収め、下側を先に掛けます。Nextruder側へ閉じ、M3×10で固定します。ベッドの保護材を外します。|Tuck the wires inside. Hook the bottom first, close toward the Nextruder and secure with M3×10. Remove the bed protection.|Vodiče uložte dovnitř. Nejprve zahákněte spodní část, kryt přitlačte k Nextruderu a zajistěte M3×10. Odstraňte ochranu podložky.|Leitungen innen verstauen. Unten einhaken, zum Nextruder schließen und mit M3×10 befestigen. Heizbettschutz entfernen.',[858,879],'lb-cover-in'),
 step('上面カバーを戻す|Refit the top cover|Nasazení horního krytu|Oberen Deckel montieren','右奥のフレームと前側のくぼみに合わせます。公式写真の位置にナイロンリベット2本で固定します。|Align with the rear right frame and front recess. Secure with two nylon rivets at the positions in the official photo.|Srovnejte s pravým zadním rámem i předním vybráním. Upevněte dvěma nylonovými nýty podle oficiální fotografie.|An hinterem rechten Rahmen und vorderer Aussparung ausrichten. Mit zwei Nylonnieten gemäß offiziellem Foto befestigen.',[87,'ventBlock'],'lb-top-in'),
 step('電源を入れる|Power on|Zapnutí tiskárny|Drucker einschalten','ドアを閉じ、電源コードを接続して電源を入れます。|Close the door, reconnect power and switch on.|Zavřete dvířka, připojte napájení a zapněte tiskárnu.|Tür schließen, Netzkabel anschließen und einschalten.',['psu','lcd']),
 step('Selftestを実行する|Run the Selftest|Spuštění Selftestu|Selbsttest ausführen','Control → Calibrations & TestsからSelftestを実行します。画面に従い、すべて緑のチェックになってから使用を再開します。|Run Selftest from Control → Calibrations & Tests. Follow the display and resume use only after all tests pass with green checks.|V Control → Calibrations & Tests spusťte Selftest. Řiďte se displejem a pokračujte až po zeleném potvrzení všech testů.|Selftest unter Control → Calibrations & Tests starten. Display folgen und Drucker erst nach grüner Bestätigung aller Tests wieder verwenden.',['lcd'],null,{firmwareActions:["selftest"]})
]};
LOVEBOARD_TASK.pdf=LOVEBOARD_PDF;LOVEBOARD_TASK.steps.forEach((s,i)=>Object.assign(s,{number:i+1,page:LOVEBOARD_PDF_PAGES[i]}));

// Keep the hotend fully seated while tightening both thumbscrews.
LOVEBOARD_TASK.revision=2;
LOVEBOARD_TASK.steps[23]={...LOVEBOARD_TASK.steps[23],body:["ケーブルを少し斜め前へ向け、ホットエンドを奥まで上へ押し込みます。ファンシュラウドのくぼみに収まり、周囲に隙間があることを確認します。押し上げたままつまみネジ2本を締めます。ホットエンドはシュラウドの下へ突き出さない位置に合わせます。","Point the cables slightly forward and fully push the hotend upward into the heatsink. Check that it sits in the fan-shroud recess with clearance around it. Keep pushing upward while tightening both thumbscrews. The hotend must not protrude below the shroud.","Kabely natočte mírně dopředu a hotend zcela zasuňte vzhůru do chladiče. Musí zapadnout do vybrání krytu ventilátoru s volným prostorem kolem. Při dotahování obou ručních šroubů jej stále tlačte nahoru. Nesmí vyčnívat pod kryt.","Kabel leicht nach vorn ausrichten und das Hotend vollständig nach oben in den Kühlkörper schieben. Es muss mit Abstand zur Umgebung in der Aussparung der Lüfterdüse sitzen. Beim Festziehen beider Rändelschrauben weiter nach oben drücken. Das Hotend darf nicht unter der Lüfterdüse hervorstehen."]};
LOVEBOARD_TASK.steps[24]={...LOVEBOARD_TASK.steps[24],body:["銅色のリングが見えない位置まで挿入できているか確認します。挿入が浅いと熱が十分に伝わらず、詰まりの原因になります。リングが見える場合はつまみネジを緩め、ホットエンドを押し上げながら締め直します。","Check that the copper ring is hidden inside the heatsink. Incomplete insertion reduces heat transfer and can cause clogs. If the ring is visible, loosen the thumbscrews, push the hotend upward and retighten them while holding it up.","Zkontrolujte, že měděný kroužek není vidět. Neúplné zasunutí zhoršuje přenos tepla a může způsobit ucpání. Pokud je kroužek vidět, povolte ruční šrouby, hotend zatlačte vzhůru a v této poloze je znovu dotáhněte.","Prüfen, dass der Kupferring im Kühlkörper verborgen ist. Unvollständiges Einsetzen verschlechtert die Wärmeübertragung und kann Verstopfungen verursachen. Bei sichtbarem Ring die Rändelschrauben lösen, das Hotend nach oben drücken und so gehalten wieder festziehen."]};
